{
  "manifest_version": 3,
  "name": "ChatGPT Conversation Exporter",
  "version": "1.0.0",
  "description": "Export the current ChatGPT conversation as Markdown, HTML, JSON, or PDF.",
  "action": { "default_popup": "popup/popup.html" },
  "background": { "service_worker": "background.js", "type": "module" },
  "permissions": ["activeTab", "scripting", "storage", "downloads", "clipboardWrite", "commands"],
  "host_permissions": ["https://chat.openai.com/*"],
  "options_ui": { "page": "options/options.html", "open_in_tab": true },
  "commands": {
    "export-markdown": { "suggested_key": { "default": "Alt+Shift+E" }, "description": "Export as Markdown" }
  }
}

// Inject (if needed) and ask the content script to export
async function requestExport(format) {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (!tab || !/^https:\/\/chat\.openai\.com\//.test(tab.url || "")) {
    return alert("Open a ChatGPT conversation first.");
  }

  // Ensure content script is present
  await chrome.scripting.executeScript({
    target: { tabId: tab.id },
    files: ["content.js"]
  });

  const payload = await chrome.tabs.sendMessage(tab.id, { type: "EXPORT_CONVERSATION", format });
  if (!payload) return;

  // handle PDF via new tab print, else download
  if (format === "pdf") {
    const blob = new Blob([payload.html], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const pdfTab = await chrome.tabs.create({ url });
    // user prints to PDF manually; or inject window.print() if you prefer:
    // setTimeout(() => chrome.scripting.executeScript({ target: { tabId: pdfTab.id }, func: () => window.print() }), 500);
  } else {
    const { filename, mime, contentBase64 } = payload.download;
    await chrome.downloads.download({
      url: `data:${mime};base64,${contentBase64}`,
      filename,
      saveAs: true
    });
  }
}

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  if (msg?.type === "EXPORT_REQUEST") {
    requestExport(msg.format).then(() => sendResponse(true));
    return true;
  }
});

chrome.commands.onCommand.addListener((cmd) => {
  if (cmd === "export-markdown") requestExport("md");
});

document.querySelectorAll("button[data-format]").forEach(btn => {
  btn.addEventListener("click", async () => {
    const format = btn.dataset.format;
    chrome.runtime.sendMessage({ type: "EXPORT_REQUEST", format });
    window.close();
  });
});

// Utilities
const b64 = (str) => btoa(unescape(encodeURIComponent(str)));
const downloadBundle = (filename, mime, str) => ({
  filename,
  mime,
  contentBase64: b64(str)
});

function nowStamp() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}_${pad(d.getHours())}-${pad(d.getMinutes())}`;
}

// Attempt multiple DOM patterns to extract messages robustly
function collectMessages() {
  const root = document;
  const results = [];

  // Try new/primary selector first
  let turns = root.querySelectorAll('[data-testid="conversation-turn"], [data-message-author-role], article');
  if (!turns.length) {
    // Fallback: blocks within the main scroll area (very defensive)
    turns = root.querySelectorAll('main div:has([role="presentation"])');
  }

  turns.forEach((el) => {
    // Role detection (robust fallback strategy)
    let role =
      el.getAttribute("data-message-author-role") ||
      el.querySelector('[data-message-author-role]')?.getAttribute("data-message-author-role") ||
      (el.textContent?.trim().startsWith("You:") ? "user" : null);

    // Heuristic: look for avatar labels or headings
    if (!role) {
      const aria = el.getAttribute("aria-label") || "";
      if (/assistant|gpt/i.test(aria)) role = "assistant";
      else if (/you|user/i.test(aria)) role = "user";
    }
    if (!role) role = /copy code|```/.test(el.textContent) ? "assistant" : "user";

    // Message content node (prefer rich content container)
    const contentNode =
      el.querySelector('[data-testid="markdown"], .markdown, .prose, .whitespace-pre-wrap') || el;

    // Extract HTML and plaintext; keep code blocks and images
    const clone = contentNode.cloneNode(true);

    // Remove UI chrome like buttons / toolbars
    clone.querySelectorAll('button, svg, [role="toolbar"], [data-testid="toolbar"]').forEach(n => n.remove());

    // Normalize images to data URLs if already loaded
    const images = Array.from(clone.querySelectorAll('img'));
    const imagePromises = images.map(async (img) => {
      try {
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        const tempImg = new Image();
        tempImg.crossOrigin = "anonymous";
        tempImg.src = img.src;
        await tempImg.decode();
        canvas.width = tempImg.naturalWidth; canvas.height = tempImg.naturalHeight;
        ctx.drawImage(tempImg, 0, 0);
        img.setAttribute("src", canvas.toDataURL("image/png"));
      } catch (e) { /* ignore if blocked */ }
    });

    results.push({
      role,
      htmlNode: clone,
      completeImages: Promise.allSettled(imagePromises)
    });
  });

  return results;
}

function htmlFromNodes(nodes) {
  return nodes.map(n => n.outerHTML).join("\n");
}

function htmlDocument(bodyInner, title = "ChatGPT Export") {
  return `<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>${title}</title>
  <link rel="stylesheet" href="${chrome.runtime.getURL('styles/export.css')}">
</head>
<body>
${bodyInner}
</body>
</html>`;
}

// Convert a node tree to Markdown (preserve code blocks)
function nodeToMarkdown(node) {
  // Very lightweight HTML→MD pass; good enough for v1
  // You can swap in a bundled converter later if desired.
  const walker = document.createTreeWalker(node, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
  let md = "";
  let codeBlock = false;

  while (walker.nextNode()) {
    const n = walker.currentNode;
    if (n.nodeType === Node.TEXT_NODE) {
      md += n.nodeValue.replace(/\s+/g, " ");
      continue;
    }
    if (n.tagName === "BR") md += "  \n";
    if (/^H[1-6]$/.test(n.tagName)) md += `\n\n${"#".repeat(n.tagName[1])} `;
    if (n.tagName === "P") md += `\n\n`;
    if (n.tagName === "UL") md += `\n`;
    if (n.tagName === "OL") md += `\n`;
    if (n.tagName === "LI") md += `\n- `;
    if (n.tagName === "CODE" && n.parentElement?.tagName !== "PRE") md += "`";
    if (n.tagName === "PRE") {
      const code = n.querySelector("code");
      const lang = (code?.className || "").match(/language-([a-z0-9+#-]+)/i)?.[1] || "";
      md += `\n\n\`\`\`${lang}\n${code?.innerText || n.innerText}\n\`\`\`\n\n`;
      codeBlock = true;
    }
    if (n.tagName === "IMG") {
      const alt = n.getAttribute("alt") || "image";
      const src = n.getAttribute("src") || "";
      md += `\n\n![${alt}](${src})\n\n`;
    }
  }
  if (!codeBlock) md = md.trim() + "\n";
  return md;
}

function serialize(messages, format, opts) {
  const title = document.title.replace(/\s*\|\s*ChatGPT.*/i, "") || "ChatGPT Conversation";
  const ts = nowStamp();
  const safeTitle = title.replace(/[^\w\-]+/g, "_").slice(0, 60);

  const normalized = messages.map(m => ({
    role: m.role,
    html: m.htmlNode.outerHTML,
    text: m.htmlNode.innerText
  }));

  if (format === "json") {
    const json = JSON.stringify({ title, exported_at: new Date().toISOString(), messages: normalized }, null, 2);
    return {
      html: null,
      download: downloadBundle(`${safeTitle}_${ts}.json`, "application/json", json)
    };
  }

  if (format === "html" || format === "pdf") {
    const body = normalized.map((m, i) =>
      `<section class="msg ${m.role}">
         <header>${m.role.toUpperCase()} #${i+1}</header>
         <article>${m.html}</article>
       </section>`
    ).join("\n");
    const html = htmlDocument(body, title);
    return {
      html,
      download: format === "html"
        ? downloadBundle(`${safeTitle}_${ts}.html`, "text/html;charset=utf-8", html)
        : { filename: `${safeTitle}_${ts}.pdf` } // handled by background via print
    };
  }

  // default: markdown
  const mdChunks = normalized.map((m, i) => {
    const wrapper = document.createElement("div");
    wrapper.innerHTML = m.html;
    const md = nodeToMarkdown(wrapper);
    return `### ${m.role.toUpperCase()} #${i+1}\n\n${md}`;
  });
  const md = `# ${title}\n_Exported: ${new Date().toISOString()}_\n\n${mdChunks.join("\n")}`;
  return {
    html: null,
    download: downloadBundle(`${safeTitle}_${ts}.md`, "text/markdown;charset=utf-8", md)
  };
}

async function exportConversation(format) {
  const msgs = collectMessages();
  // Wait for images to settle (best-effort)
  await Promise.allSettled(msgs.map(m => m.completeImages));
  const options = await chrome.storage.sync.get({
    includeTimestamps: false,
    includeImages: true
  });
  return serialize(msgs, format, options);
}

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  if (msg?.type === "EXPORT_CONVERSATION") {
    exportConversation(msg.format).then(payload => sendResponse(payload));
    return true;
  }
});

body { font-family: ui-sans-serif, system-ui, -apple-system, Arial, sans-serif; line-height: 1.55; padding: 32px; max-width: 900px; margin: auto; }
section.msg { border: 1px solid #ddd; border-radius: 12px; padding: 16px; margin: 16px 0; }
section.msg > header { font-size: 12px; letter-spacing: .08em; color: #666; margin-bottom: 8px; }
section.msg.user { background: #fafafa; }
pre { overflow: auto; padding: 12px; border-radius: 10px; border: 1px solid #eee; }
code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace; }
img { max-width: 100%; height: auto; }
@media print { section.msg { break-inside: avoid; } }

(async () => {
  const opts = await chrome.storage.sync.get({ includeTimestamps: false, includeImages: true });
  includeTimestamps.checked = opts.includeTimestamps;
  includeImages.checked = opts.includeImages;

  save.addEventListener("click", async () => {
    await chrome.storage.sync.set({
