{
  "manifest_version": 3,
  "name": "ChatGPT Export — MVP Button",
  "version": "0.0.1",
  "description": "Injects an Export button into each ChatGPT message and echoes on click.",
  "host_permissions": ["https://chat.openai.com/*"],
  "content_scripts": [
    {
      "matches": ["https://chat.openai.com/*"],
      "js": ["content.js"],
      "run_at": "document_idle"
    }
  ]
}

// Small, defensive MVP to show an "Export" button per message and echo on click.
// Strategy:
// 1) Try to piggyback into the native per-message toolbar (role=toolbar or buttons like Copy/Speak).
// 2) If not found, overlay a tiny button at the message's bottom-right corner.
// Shadow DOM isolates styles so site changes don't easily break us.

const BTN_ID = "cgpt-export-btn";
const HOST_ATTR = "data-cgpt-export-host";
const MARK_ATTR = "data-cgpt-export-mounted";

// Utility: create a shadow host with our button
function createShadowButton(onClick) {
  const host = document.createElement("span");
  host.setAttribute(HOST_ATTR, "1");
  const shadow = host.attachShadow({ mode: "open" });

  // Minimal, neutral styles that inherit color
  shadow.innerHTML = `
    <style>
      :host { all: initial; }
      .btn {
        display: inline-flex; align-items: center; gap: 6px;
        font: 600 12px/1.2 ui-sans-serif, system-ui, -apple-system, Arial, sans-serif;
        padding: 6px 8px; border-radius: 8px;
        background: rgba(127,127,127,0.1); border: 1px solid rgba(127,127,127,0.25);
        cursor: pointer; user-select: none; white-space: nowrap;
      }
      .btn:hover { background: rgba(127,127,127,0.18); }
      .btn:focus { outline: 2px solid rgba(0,0,0,0.3); outline-offset: 2px; }
      .ico { width: 14px; height: 14px; display: inline-block; }
      .label { color: inherit; }
    </style>
    <button id="${BTN_ID}" class="btn" type="button" aria-label="Export">
      <svg class="ico" viewBox="0 0 24 24" aria-hidden="true">
        <path d="M12 3v10m0 0l-3.5-3.5M12 13l3.5-3.5M5 21h14a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
      <span class="label">Export</span>
    </button>
  `;

  shadow.getElementById(BTN_ID).addEventListener("click", onClick);
  return host;
}

function echo(messageEl, scope = "this") {
  const idx = [...document.querySelectorAll(getMessageSelector())].indexOf(messageEl);
  const who = messageEl.getAttribute("data-message-author-role") || "unknown";
  const note = `Export clicked on message #${idx + 1} (${who}), scope: ${scope}`;
  console.log("[ChatGPT Export MVP]", note, messageEl);
  alert(note); // echo for MVP
}

// Heuristics to find message roots and their toolbars
function getMessageSelector() {
  // Prefer stable attributes first
  return [
    '[data-testid="conversation-turn"]',
    '[data-message-author-role]',
    'article' // fallback: read-only/shared pages often use <article>
  ].join(',');
}

function findToolbar(messageEl) {
  // Look for something that behaves like the action row
  // 1) role=toolbar
  let tb = messageEl.querySelector('[role="toolbar"]');
  if (tb) return tb;

  // 2) A container that includes known buttons (Copy / Speak). Match by text, title, or aria-label.
  const buttonLike = Array.from(messageEl.querySelectorAll('button, [role="button"]')).filter(b => {
    const t = (b.getAttribute('aria-label') || b.getAttribute('title') || b.textContent || "").toLowerCase();
    return /copy|speak|rate|regenerate|good answer|bad answer/.test(t);
  });
  if (buttonLike.length) {
    // Pick the closest common container of those buttons
    return buttonLike[0].closest('div,nav,section') || buttonLike[0].parentElement;
  }

  return null;
}

function mountPiggyback(messageEl) {
  const toolbar = findToolbar(messageEl);
  if (!toolbar) return false;
  if (toolbar.querySelector(`[${HOST_ATTR}]`)) return true; // already mounted here

  const host = createShadowButton(() => echo(messageEl, "toolbar"));
  // Insert at end of toolbar button row
  toolbar.appendChild(host);
  return true;
}

function mountOverlay(messageEl) {
  if (messageEl.querySelector(`[${HOST_ATTR}]`)) return true; // already mounted here

  // Ensure the message container is a positioning context (non-destructive)
  const hadInlinePos = messageEl.style.position;
  if (getComputedStyle(messageEl).position === "static") {
    messageEl.style.position = "relative";
    messageEl.setAttribute("data-cgpt-pos-added", "1");
  }

  const host = document.createElement("span");
  host.setAttribute(HOST_ATTR, "1");
  host.style.position = "absolute";
  host.style.right = "8px";
  host.style.bottom = "8px";
  host.style.zIndex = "5"; // low but above content
  const shadowBtn = createShadowButton(() => echo(messageEl, "overlay"));
  host.appendChild(shadowBtn);
  messageEl.appendChild(host);
  return true;
}

function mountForMessage(messageEl) {
  if (messageEl.getAttribute(MARK_ATTR)) return; // already processed
  if (mountPiggyback(messageEl) === false) {
    mountOverlay(messageEl);
  }
  messageEl.setAttribute(MARK_ATTR, "1");
}

// Initial scan + observer
function init() {
  // Only on ChatGPT conversation routes
  if (!/https:\/\/chat\.openai\.com\/.*/.test(location.href)) return;

  const processAll = () => {
    document.querySelectorAll(getMessageSelector()).forEach(mountForMessage);
  };

  processAll();

  const obs = new MutationObserver((muts) => {
    let changed = false;
    for (const m of muts) {
      if (m.addedNodes && m.addedNodes.length) { changed = true; break; }
      if (m.type === "attributes") { changed = true; break; }
    }
    if (changed) {
      // Debounce lightly
      clearTimeout(init._t);
      init._t = setTimeout(processAll, 120);
    }
  });

  // Observe the whole document; ChatGPT is an SPA and re-renders chunks
  obs.observe(document.documentElement, { childList: true, subtree: true, attributes: true });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", init, { once: true });
} else {
  init();
}

