/* ===========================
   Conversation Harvester
   =========================== */

/** Data model:
 * {
 *   meta: { title, url, exported_at },
 *   messages: [
 *     {
 *       index, id, role, timestamp,
 *       html, text,
 *       segments: [
 *         { type: 'text', md, html? },
 *         { type: 'code', language, text },
 *         { type: 'image', alt, src },
 *         { type: 'table', html },
 *         { type: 'math', latex } // best-effort
 *       ]
 *     }
 *   ]
 * }
 */

// Entry point used by the button
async function onExportClick() {
  try {
    const harvest = await harvestConversation();
    // save to global for dev convenience
    window.__CGPT_EXPORT = window.__CGPT_EXPORT || {};
    window.__CGPT_EXPORT.lastHarvest = harvest;

    console.log('[ChatGPT Export Overlay] Harvested conversation:', harvest);

    const json = JSON.stringify(harvest, null, 2);
    // Try to copy (allowed from user gesture)
    let copied = false;
    try {
      await navigator.clipboard.writeText(json);
      copied = true;
    } catch (e) {
      // ignore
    }
    alert(`${copied ? 'Copied JSON to clipboard.\n\n' : ''}Harvested ${harvest.messages.length} messages from ${harvest.meta.url}`);
  } catch (err) {
    console.error('[ChatGPT Export Overlay] Harvest failed:', err);
    alert('Failed to harvest conversation. Check console for details.');
  }
}

async function harvestConversation() {
  // 1) Identify message containers (robust selector set)
  const messageEls = selectMessageElements();

  // 2) Normalize each message
  const messages = [];
  let idx = 0;
  for (const el of messageEls) {
    const msg = await normalizeMessage(el, idx++);
    messages.push(msg);
  }

  // 3) Build final payload
  const meta = {
    title: safeTitle(document.title.replace(/\s*\|\s*ChatGPT.*/i, '') || 'ChatGPT Conversation'),
    url: location.href,
    exported_at: new Date().toISOString()
  };

  return { meta, messages };
}

function selectMessageElements() {
  // Prefer stable attributes; keep fallbacks for shared views
  const selectors = [
    '[data-testid="conversation-turn"]',
    '[data-message-author-role]',
    'article',
    'main article',
    'div[role="article"]'
  ];
  // Use a Set to preserve order but avoid duplicates across selectors
  const seen = new Set();
  const out = [];
  for (const sel of selectors) {
    document.querySelectorAll(sel).forEach(el => {
      // Only accept elements that contain actual text/content
      if (seen.has(el)) return;
      const text = el.textContent?.trim() || '';
      if (!text) return;
      seen.add(el);
      out.push(el);
    });
  }
  return out;
}

async function normalizeMessage(el, index) {
  const role = detectRole(el);
  const id = el.getAttribute('id') || el.dataset.messageId || `msg-${index+1}`;
  const timestamp = detectTimestamp(el);

  // Clone the rich content container; try best known containers first
  const contentNode =
    el.querySelector('[data-testid="markdown"], .markdown, .prose, .whitespace-pre-wrap, article, div') || el;
  const clone = contentNode.cloneNode(true);

  // Strip obvious UI chrome
  clone.querySelectorAll('button, [role="toolbar"], svg[aria-hidden="true"]').forEach(n => n.remove());

  // Extract segments
  const segments = [];

  // Code blocks
  clone.querySelectorAll('pre code').forEach(code => {
    segments.push({
      type: 'code',
      language: (code.className || '').match(/language-([a-z0-9+#-]+)/i)?.[1] || '',
      text: code.innerText
    });
  });

  // Images
  clone.querySelectorAll('img').forEach(img => {
    segments.push({
      type: 'image',
      alt: img.getAttribute('alt') || '',
      src: img.getAttribute('src') || ''
    });
  });

  // Tables
  clone.querySelectorAll('table').forEach(tbl => {
    segments.push({
      type: 'table',
      html: tbl.outerHTML
    });
  });

  // Math (very best-effort; looks for LaTeX blocks/spans)
  clone.querySelectorAll('span.math, .katex-mathml, .math.math-inline, .math.math-display').forEach(m => {
    const latex = m.textContent?.trim() || '';
    if (latex) segments.push({ type: 'math', latex });
  });

  // Rendered HTML snapshot (post-clean)
  const html = clone.innerHTML;

  // Plain text
  const text = clone.innerText || el.innerText || '';

  // Remaining text segment in Markdown (rough)
  const md = toMarkdownBasic(clone);
  if (md.trim()) {
    segments.unshift({ type: 'text', md, html }); // include html snapshot for this text segment
  }

  return { index, id, role, timestamp, html, text, segments };
}

function detectRole(el) {
  // Direct attribute
